"""
Execution-grounded verification of agent-authored workspaces.

This module implements the ExecutionHarness which verifies code by actually
running it (parsing, installing, importing, testing) rather than relying on
textual analysis or file counts.
"""

import ast
import os
import sys
import subprocess
import tempfile
import shutil
import time
import re
import json
import tomllib
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any, Tuple, Iterable

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Import artifacts module if available, otherwise define fallbacks
try:
    from hae.evaluation.artifacts import (
        is_generated_path,
        is_malformed_path,
        sanitize_path,
        filter_bundle,
        partition_bundle,
        count_source_files,
        EXCLUDED_DIR_SEGMENTS,
        EXCLUDED_DIR_SUFFIXES
    )
except ImportError:
    # Fallback definitions if artifacts.py is not yet available or import fails
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if path != path.strip():
            return True
        if '*' in path or '`' in path:
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def sanitize_path(path: str) -> str:
        path = path.strip()
        path = path.replace('*', '').replace('`', '')
        if path.startswith('-'):
            path = path[1:]
        if path.endswith('.') or path.endswith('~'):
            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        count = 0
        for path in bundle:
            if not is_generated_path(path) and not is_malformed_path(path):
                if any(path.endswith(s) for s in suffixes):
                    count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files} (Python: {self.python_files})")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("-" * 40)
        for g in self.gates:
            status_icon = "PASS" if g.passed else ("SKIP" if g.status == SKIPPED else "FAIL")
            lines.append(f"[{status_icon}] {g.name}: {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "gate_status": self.gate_status,
            "pass_rate": self.pass_rate
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to match fenced code blocks with optional language and optional filename hint
    # Pattern: ```[lang] [filename]\n content \n```
    # We look for lines starting with ```
    pattern = r"```(?:\w+)?(?:\s+([^\n]+))?\n(.*?)\n```"
    matches = re.findall(pattern, text, re.DOTALL)

    bundle = {}
    for i, (filename_hint, content) in enumerate(matches):
        # Try to determine path
        path = None
        if filename_hint:
            # Clean up filename hint
            hint = filename_hint.strip()
            # Remove common prefixes like "Path:", "File:", etc.
            hint = re.sub(r"^(Path|File|Filename|Name)\s*[:=]\s*", "", hint, flags=re.IGNORECASE)
            # If it looks like a path, use it
            if '/' in hint or '\\' in hint or '.' in hint:
                path = sanitize_path(hint)

        if not path:
            # Fallback: generate a name based on index
            path = f"extracted_block_{i}.py"

        # Ensure path is valid
        if is_malformed_path(path):
            path = sanitize_path(path)
            if is_malformed_path(path):
                path = f"extracted_block_{i}.py"

        bundle[path] = content

    return bundle


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
                source = 'workspace'
            elif hasattr(workspace, 'files'):
                bundle = workspace.files
                source = 'workspace'
            elif isinstance(workspace, dict):
                bundle = workspace
                source = 'workspace'

        # If bundle is empty, try extracting from deliverable text
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        if not bundle:
            # Empty workspace
            return self._empty_report(source)

        return self.verify_bundle(bundle, source=source)

    def _empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast_parse', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='metadata_check', detail='No build metadata found'),
            GateResult(name='smoke', status=FAILED, method='import_check', detail='No modules to import'),
            GateResult(name='tests', status=FAILED, method='pytest_run', detail='No test files found'),
            GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No telemetry usage found'),
        ]
        return VerificationReport(
            gates=gates,
            score_penalty=len(gates) * self.penalty_per_gate,
            authored_files=0,
            python_files=0,
            source=source
        )

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to remove generated/malformed paths
        authored_bundle = filter_bundle(bundle)

        # Count files
        authored_files = len(authored_bundle)
        python_files = count_source_files(authored_bundle, suffixes=('.py',))

        if authored_files == 0:
            return self._empty_report(source)

        # Create temp directory
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to disk
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Prune excluded dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        try:
                            with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        authored_files = len(authored)
        python_files = count_source_files(authored, suffixes=('.py',))

        if authored_files == 0:
            return self._empty_report(source)

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, authored))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source
        )

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        py_files = [p for p in authored if p.endswith('.py')]

        if not py_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast_parse',
                detail='No Python files found',
                duration_s=time.time() - start
            )

        errors = []
        for path in py_files:
            full_path = os.path.join(workdir, path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")
            except Exception as e:
                errors.append(f"{path}: {e}")

        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast_parse',
                detail='Syntax errors found: ' + '; '.join(errors[:5]),
                duration_s=time.time() - start,
                evidence={'errors': errors}
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast_parse',
            detail=f"All {len(py_files)} Python files parsed successfully",
            duration_s=time.time() - start
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Check for metadata files
        metadata_files = ['pyproject.toml', 'setup.py', 'setup.cfg']
        found_metadata = None

        for mf in metadata_files:
            if mf in authored:
                found_metadata = mf
                break

        if not found_metadata:
            return GateResult(
                name='build',
                status=FAILED,
                method='metadata_check',
                detail='No build metadata (pyproject.toml, setup.py, setup.cfg) found',
                duration_s=time.time() - start
            )

        # Validate pyproject.toml if present
        if found_metadata == 'pyproject.toml':
            try:
                with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                    data = tomllib.load(f)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(k in data for k in ['project', 'build-system', 'tool']):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='toml_validation',
                        detail='pyproject.toml missing required tables ([project], [build-system], or [tool])',
                        duration_s=time.time() - start
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='toml_validation',
                    detail=f'Invalid pyproject.toml: {e}',
                    duration_s=time.time() - start
                )

        # Try to install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], 
                           capture_output=True, timeout=10, check=True)

            # Run pip install
            cmd = [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation']
            result = subprocess.run(
                cmd,
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            if result.returncode != 0:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip_install',
                    detail=f'pip install failed: {result.stderr[:500]}',
                    duration_s=time.time() - start,
                    evidence={'stderr': result.stderr, 'stdout': result.stdout}
                )

            return GateResult(
                name='build',
                status=PASSED,
                method='pip_install',
                detail='Package installed successfully',
                duration_s=time.time() - start
            )

        except FileNotFoundError:
            return GateResult(
                name='build',
                status=SKIPPED,
                method='pip_install',
                detail='pip not available',
                duration_s=time.time() - start
            )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail='pip install timed out',
                duration_s=time.time() - start
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail=f'Build check error: {e}',
                duration_s=time.time() - start
            )

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Find non-test authored modules
        modules = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                continue
            # Convert path to module name
            # Remove .py
            mod_path = path[:-3]
            # Replace / with .
            mod_name = mod_path.replace('/', '.').replace('\\', '.')
            # Handle __init__.py
            if mod_name.endswith('.__init__'):
                mod_name = mod_name[:-9]
            if mod_name:
                modules.append(mod_name)

        if not modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='No importable non-test modules found',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        env = os.environ.copy()
        python_path = [workdir]
        if os.path.exists(src_dir):
            python_path.append(src_dir)
        env['PYTHONPATH'] = os.pathsep.join(python_path)

        # Try importing each module
        failed_modules = []
        skipped_modules = []

        for mod_name in modules:
            try:
                # Run a subprocess to import
                code = f"import {mod_name}"
                result = subprocess.run(
                    [self.python_executable, '-c', code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=10
                )

                if result.returncode != 0:
                    stderr = result.stderr
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package
                        # If the module itself is not found, it might be a path issue or missing dep
                        # If a dependency is missing, it's skipped
                        # We assume if the module name itself is not found, it's a failure of the workspace structure
                        # But if it's a sub-dependency, it's skipped.
                        # Simple heuristic: if the error mentions the module name, it's a failure.
                        # If it mentions another package, it's skipped.
                        if mod_name.split('.')[0] in stderr:
                             failed_modules.append(mod_name)
                        else:
                             skipped_modules.append(mod_name)
                    else:
                        failed_modules.append(mod_name)
            except Exception:
                failed_modules.append(mod_name)

        if failed_modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail=f"Failed to import: {', '.join(failed_modules[:5])}",
                duration_s=time.time() - start,
                evidence={'failed': failed_modules}
            )

        if skipped_modules and not failed_modules:
            # If all modules were skipped due to missing deps, return SKIPPED
            if len(skipped_modules) == len(modules):
                return GateResult(
                    name='smoke',
                    status=SKIPPED,
                    method='import_check',
                    detail='All modules skipped due to missing third-party dependencies',
                    duration_s=time.time() - start
                )

        return GateResult(
            name='smoke',
            status=PASSED,
            method='import_check',
            detail=f"All {len(modules)} modules imported successfully",
            duration_s=time.time() - start
        )

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Find test files
        test_files = [p for p in authored if 'test' in os.path.basename(p).lower() and p.endswith('.py')]

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method='pytest_run',
                detail='No test files found',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        env = os.environ.copy()
        python_path = [workdir]
        if os.path.exists(src_dir):
            python_path.append(src_dir)
        env['PYTHONPATH'] = os.pathsep.join(python_path)

        # Check if pytest is available
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], 
                           capture_output=True, timeout=10, check=True)
            has_pytest = True
        except Exception:
            has_pytest = False

        if has_pytest:
            # Run pytest
            cmd = [self.python_executable, '-m', 'pytest', '-v', '--tb=short']
            # Add test files explicitly or let pytest discover
            # Let pytest discover in workdir
            result = subprocess.run(
                cmd,
                cwd=workdir,
                env=env,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            if result.returncode == 0:
                return GateResult(
                    name='tests',
                    status=PASSED,
                    method='pytest_run',
                    detail='All tests passed',
                    duration_s=time.time() - start
                )
            else:
                # Check if failure was due to ModuleNotFoundError
                if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                    # If tests couldn't run due to missing deps, skip
                    # But if some tests ran and failed, it's a failure.
                    # Pytest exit code 1 means tests failed. Exit code 2 means interrupted.
                    # If it's a collection error due to missing module, it might be 2 or 1.
                    # Heuristic: if "ModuleNotFoundError" is in output, likely skipped.
                    return GateResult(
                        name='tests',
                        status=SKIPPED,
                        method='pytest_run',
                        detail='Tests skipped due to missing dependencies',
                        duration_s=time.time() - start
                    )

                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest_run',
                    detail='Tests failed',
                    duration_s=time.time() - start,
                    evidence={'stdout': result.stdout[-1000:], 'stderr': result.stderr[-1000:]}
                )
        else:
            # Stdlib fallback
            # Run a script that imports test files and runs unittest
            script = """
import sys
import unittest
import importlib
import os

# Add paths
sys.path.insert(0, os.getcwd())
sys.path.insert(0, os.path.join(os.getcwd(), 'src'))

test_files = []
for root, dirs, files in os.walk('.'):
    for f in files:
        if 'test' in f.lower() and f.endswith('.py'):
            test_files.append(os.path.join(root, f))

if not test_files:
    print("NO_TESTS")
    sys.exit(0)

loader = unittest.TestLoader()
suite = unittest.TestSuite()

for tf in test_files:
    try:
        # Convert path to module name
        mod_path = tf.replace('./', '').replace('/', '.').replace('\\\\', '.')
        if mod_path.endswith('.py'):
            mod_path = mod_path[:-3]
        if mod_path.endswith('.__init__'):
            mod_path = mod_path[:-9]

        mod = importlib.import_module(mod_path)

        # Load tests from module
        suite.addTests(loader.loadTestsFromModule(mod))

        # Also look for bare test_ functions
        for attr in dir(mod):
            if attr.startswith('test_'):
                func = getattr(mod, attr)
                if callable(func):
                    # Wrap in a TestCase
                    class DynamicTest(unittest.TestCase):
                        def runTest(self):
                            func()
                    suite.addTest(DynamicTest())
    except ModuleNotFoundError as e:
        print(f"SKIP_MODULE: {e}")
    except Exception as e:
        print(f"ERROR: {e}")

runner = unittest.TextTestRunner(verbosity=2)
result = runner.run(suite)

if result.wasSuccessful():
    sys.exit(0)
else:
    sys.exit(1)
"""
            try:
                result = subprocess.run(
                    [self.python_executable, '-c', script],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='unittest_fallback',
                        detail='All tests passed (stdlib fallback)',
                        duration_s=time.time() - start
                    )
                else:
                    if 'SKIP_MODULE' in result.stdout or 'ModuleNotFoundError' in result.stderr:
                        return GateResult(
                            name='tests',
                            status=SKIPPED,
                            method='unittest_fallback',
                            detail='Tests skipped due to missing dependencies',
                            duration_s=time.time() - start
                        )
                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='unittest_fallback',
                        detail='Tests failed',
                        duration_s=time.time() - start,
                        evidence={'stdout': result.stdout[-1000:], 'stderr': result.stderr[-1000:]}
                    )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='unittest_fallback',
                    detail=f'Fallback runner error: {e}',
                    duration_s=time.time() - start
                )

    def _gate_telemetry(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        py_files = [p for p in authored if p.endswith('.py')]

        if not py_files:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='No Python files to analyze',
                duration_s=time.time() - start
            )

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span', 'start_span', 'get_tracer', 
            'get_tracer_provider', 'set_tracer_provider', 'get_meter'
        }

        for path in py_files:
            full_path = os.path.join(workdir, path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                tree = ast.parse(content)

                for node in ast.walk(tree):
                    # Check for import opentelemetry
                    if isinstance(node, ast.Import):
                        for alias in node.names:
                            if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                                has_import = True
                    elif isinstance(node, ast.ImportFrom):
                        if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                            has_import = True

                    # Check for calls
                    if isinstance(node, ast.Call):
                        func = node.func
                        # Direct call: get_tracer()
                        if isinstance(func, ast.Name) and func.id in tracer_methods:
                            has_call = True
                        # Attribute call: tracer.start_span()
                        elif isinstance(func, ast.Attribute) and func.attr in tracer_methods:
                            has_call = True

            except Exception:
                pass

        if has_import and has_call:
            return GateResult(
                name='telemetry',
                status=PASSED,
                method='ast_analysis',
                detail='OpenTelemetry import and tracer/span calls found',
                duration_s=time.time() - start
            )
        elif has_import:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='OpenTelemetry imported but no tracer/span calls found',
                duration_s=time.time() - start
            )
        else:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='No OpenTelemetry usage found',
                duration_s=time.time() - start
            )
